in:
shader_type spatial;
render_mode blend_mix, cull_disabled, unshaded;

group_uniforms look;
uniform vec4 tint : source_color = vec4(1.0, 0.5, 0.2, 1.0);
uniform float speed : hint_range(0.0, 10.0, 0.1) = 2.0;
instance uniform float glow = 1.0;
uniform sampler2D albedo_map : source_color, filter_nearest;

void fragment() {
  float pulse = 0.5 + 0.5 * sin(TIME * speed);
  ALBEDO = tint.rgb * texture(albedo_map, UV).rgb;
  EMISSION = tint.rgb * pulse * glow;
  ALPHA = tint.a;
}

value.material:
material {
    name : "pulse",
    shadingModel : unlit,
    blending : transparent,
    culling : none,
    doubleSided : true,
    requires : [ uv0 ],
    parameters : [
        { type : float4, name : "tint" },
        { type : float, name : "speed" },
        { type : float, name : "glow" },
        { type : sampler2d, name : "albedo_map" }
    ],
}
fragment {




#define tint materialParams.tint
#define speed materialParams.speed
#define glow materialParams.glow
#define albedo_map materialParams_albedo_map

void orblit_fragment(inout vec3 ALBEDO, inout float ALPHA, inout float METALLIC, inout float ROUGHNESS, inout float AO, inout vec3 EMISSION, inout vec3 NORMAL_MAP, vec2 UV, float TIME) {
  float pulse = 0.5 + 0.5 * sin(TIME * speed);
  ALBEDO = tint.rgb * texture(albedo_map, UV).rgb;
  EMISSION = tint.rgb * pulse * glow;
  ALPHA = tint.a;
}

#undef tint
#undef speed
#undef glow
#undef albedo_map
    void material(inout MaterialInputs material) {
        vec3 ALBEDO = vec3(1.0);
        float ALPHA = 1.0;
        float METALLIC = 0.0;
        float ROUGHNESS = 0.5;
        float AO = 1.0;
        vec3 EMISSION = vec3(0.0);
        vec3 NORMAL_MAP = vec3(0.0, 0.0, 1.0);
        orblit_fragment(ALBEDO, ALPHA, METALLIC, ROUGHNESS, AO, EMISSION, NORMAL_MAP, getUV0(), getUserTime().x);
        prepareMaterial(material);
        material.baseColor = vec4(ALBEDO * ALPHA, ALPHA);
        material.emissive = vec4(EMISSION, 1.0);
    }
}

